    auto pid = ProcessHelper::getProcessId(L"l2.exe");

    if (pid == 0) {
        std::cout << "Failed to find l2.exe\n";
        std::cin.get();
        return 1;
    }

    auto driverHandle = CreateFile(L"\\\\.\\MotorolaDriver", GENERIC_READ, 0, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (driverHandle == INVALID_HANDLE_VALUE) {
        std::cout << "Failed to create our driver handle.\n";
        std::cin.get();
        return 1;
    }

    // Creating a unique_ptr with a custom deleter for automatic handle closing
    auto driver = std::unique_ptr<void, decltype(&CloseHandle)>(driverHandle, &CloseHandle);

    if (driver::attach_to_process(driver.get(), pid)) {
        std::cout << "Attachment successful.\n";
    }

